// Shared signing helper (same scheme as convex/automation/signing.ts):
// signature = HMAC-SHA256(secret, `${ts}.${METHOD}.${pathAndQuery}.${rawBody}`)
const crypto = require('crypto');
const SECRET = $env.LENDLOOP_INBOUND_SIGNING_SECRET;
const BASE = ($env.LENDLOOP_CONVEX_SITE_URL || '').replace(/\/$/, '');
if (!SECRET || !BASE) throw new Error('LENDLOOP_INBOUND_SIGNING_SECRET and LENDLOOP_CONVEX_SITE_URL must be set');
function signed(method, pathAndQuery, body) {
  const rawBody = body === undefined ? '' : JSON.stringify(body);
  const ts = Math.floor(Date.now() / 1000).toString();
  const sig = crypto.createHmac('sha256', SECRET).update(`${ts}.${method}.${pathAndQuery}.${rawBody}`).digest('hex');
  return {
    url: BASE + pathAndQuery,
    rawBody,
    headers: { 'Content-Type': 'application/json', 'X-LendLoop-Timestamp': ts, 'X-LendLoop-Signature': `v1=${sig}` },
  };
}

// The Error Trigger payload differs for execution errors vs trigger errors.
const e = $input.first().json;
const execution = e.execution || {};
const body = {
  executionId: String(execution.id ?? `trigger-${e.workflow?.id ?? 'unknown'}-${Date.now()}`),
  workflow: String(e.workflow?.name ?? 'unknown workflow').slice(0, 100),
  node: execution.lastNodeExecuted ?? e.trigger?.error?.node?.name ?? undefined,
  message: String(execution.error?.message ?? e.trigger?.error?.message ?? 'Unknown error').slice(0, 1000),
  ...(execution.url ? { executionUrl: execution.url } : {}),
};
return [{ json: { report: body, ...signed('POST', '/automation/failures', body) } }];

